-- Table structure for tb_base_masterdata_customer_live
-- ----------------------------
DROP TABLE IF EXISTS `tb_base_masterdata_customer_live`;
CREATE TABLE `tb_base_masterdata_customer_live`  (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '客户居住关系表id',
  `customer_corp_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '公司客户编码',
  `comm_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '项目编码',
  `customer_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '客户编码',
  `resource_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源编码',
  `relation` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '居住关系	（1）固定选项：1-业主,2-租户,3-业主成员,4-租户成员，必填；\r\n（2）资源类别为房屋时可以选择业主、租户、业主成员、租户成员，资源类别为车位时只能选择业主；\r\n（3）资源编号当前无业主时不允许登记业主成员、租户、租户成员，当前无租户时不允许登记租户成员，否则提示“请先迁入业主、租户后再迁入成员”；当前有租户时不允许登记第二个租户，否则提示“当前已存在租户，不能重复迁入”；',
  `first_contact` int NULL DEFAULT 0 COMMENT '是否第一联系人  1-不是，2-是	（1）居住关系为业主时才显示，必填；\r\n（2）一个资源编号处于迁入状态的业主中必须且最多有一个第一联系人，默认将迁入的第一个业主设为是；\r\n（3）修改时只能将当前为迁入状态、不是第一联系人的业主改为是，同时自动将当前为迁入状态、是第一联系人的业主改为否；',
  `owner_relation` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '与户主关系（1）固定选项：0-本人/1-配偶/2-子女/3-孙子女/重孙子女/父母/祖父母/曾祖父母/兄弟/姊妹/叔父母/侄子女/亲属/员工/同事/朋友/其他；必填；\r\n（2）居住关系为业主、租户时自动默认为本人，不允许修改；',
  `householder_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '成员对应户主	居住关系为业主成员、租户成员时才显示，居住关系为业主成员时默认当前第一联系人，居住关系为租户默认当前租户；必填；',
  `active_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '居住状态，只有：迁入/迁出 1-迁入，2-迁出',
  `check_out_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '迁出原因',
  `create_user` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发起人',
  `create_date` datetime NULL DEFAULT NULL COMMENT '发起时间',
  `modify_user` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改人',
  `modify_date` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `is_delete` int NOT NULL DEFAULT 0 COMMENT '记录是否删除状态,0-正常，1-已删除',
  `delete_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '删除人',
  `delete_date` datetime NULL DEFAULT NULL COMMENT '删除时间',
  `memo` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `time_stamp` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '编辑时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_1`(`comm_id` ASC, `resource_id` ASC, `customer_id` ASC, `relation` ASC, `active_status` ASC, `first_contact` ASC, `is_delete` ASC) USING BTREE,
  INDEX `idx_2`(`is_delete` ASC, `customer_id` ASC, `relation` ASC) USING BTREE,
  INDEX `idx_3`(`is_delete` ASC, `customer_id` ASC) USING BTREE,
  INDEX `idx_4`(`is_delete` ASC, `customer_corp_id` ASC, `active_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '客户居住关系表' ROW_FORMAT = Dynamic;

